const now = new Date();
const runDateDisplay = new Intl.DateTimeFormat("fr-FR", {
  dateStyle: "full",
  timeStyle: "short",
  timeZone: "Europe/Paris",
}).format(now);

return [
  {
    json: {
      workflowName: "repo-ops - maintenance quotidienne",
      runDateIso: now.toISOString(),
      runDateDisplay,
      collectCommand: "sh /files/scripts/collect-results.sh --execute --format json",
      mailFrom: "Repo Ops <a-configurer@example.com>",
      mailTo: "a-configurer@example.com",
      workflowNotes: [
        "Configurer un credential SMTP sur le nœud Email Send après import.",
        "Remplacer les adresses placeholder dans ce nœud avant activation."
      ],
      logMessages: [
        "[workflow] Contexte d'exécution préparé.",
        "[workflow] Le script de collecte sera exécuté dans le conteneur n8n."
      ]
    }
  }
];

const result = $input.first().json;
const stdout = result.stdout ?? "{}";
let report;

try {
  report = JSON.parse(stdout);
} catch (error) {
  throw new Error(`Impossible d'analyser la sortie JSON de collect-results : ${error.message}`);
}

return [
  {
    json: {
      report,
      collectExitCode: result.exitCode ?? 0,
      collectStdout: result.stdout ?? "",
      collectStderr: result.stderr ?? "",
      logMessages: report.logMessages ?? []
    }
  }
];

const data = $input.first().json;
const report = data.report ?? {};
const scanned = report.scannedRepositories ?? [];
const created = report.createdPullRequests ?? [];
const merged = report.mergedPullRequests ?? [];
const failed = report.failedPullRequests ?? [];
const vulnerabilities = report.remainingVulnerabilities ?? [];
const actions = report.manualActions ?? [];
const logs = [...(data.logMessages ?? []), ...(report.logMessages ?? [])];

const escapeHtml = (value) => String(value)
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;")
  .replace(/\"/g, "&quot;")
  .replace(/'/g, "&#39;");

const asTextLines = (values, fallback) =>
  values.length > 0
    ? values.map((value) => `- ${typeof value === "string" ? value : JSON.stringify(value)}`).join("\n")
    : `- ${fallback}`;

const asHtmlList = (values, fallback) =>
  values.length > 0
    ? `<ul>${values
        .map((value) => `<li>${escapeHtml(typeof value === "string" ? value : JSON.stringify(value))}</li>`)
        .join("")}</ul>`
    : `<p>${escapeHtml(fallback)}</p>`;

const subject = `[repo-ops] Synthèse maintenance du ${data.runDateDisplay}`;

const text = [
  `Synthèse quotidienne repo-ops`,
  `Date d'exécution : ${data.runDateDisplay}`,
  "",
  "Dépôts scannés",
  asTextLines(scanned, "Aucun dépôt remonté par le placeholder."),
  "",
  "PR créées",
  asTextLines(created, "Aucune PR créée dans ce premier jet."),
  "",
  "PR fusionnées",
  asTextLines(merged, "Aucune PR fusionnée dans ce premier jet."),
  "",
  "PR en échec",
  asTextLines(failed, "Aucune PR en échec dans ce premier jet."),
  "",
  "Vulnérabilités restantes",
  asTextLines(vulnerabilities, "Aucune vulnérabilité remontée par le placeholder."),
  "",
  "Actions manuelles recommandées",
  asTextLines(actions, "Aucune action manuelle supplémentaire."),
  "",
  "Journal d'exécution",
  asTextLines(logs, "Aucun log supplémentaire.")
].join("\n");

const html = `
  <html lang="fr">
    <body style="font-family: Arial, sans-serif; color: #172033; line-height: 1.5;">
      <h1>Synthèse quotidienne repo-ops</h1>
      <p><strong>Date d'exécution :</strong> ${escapeHtml(data.runDateDisplay)}</p>
      <h2>Dépôts scannés</h2>
      ${asHtmlList(scanned, "Aucun dépôt remonté par le placeholder.")}
      <h2>PR créées</h2>
      ${asHtmlList(created, "Aucune PR créée dans ce premier jet.")}
      <h2>PR fusionnées</h2>
      ${asHtmlList(merged, "Aucune PR fusionnée dans ce premier jet.")}
      <h2>PR en échec</h2>
      ${asHtmlList(failed, "Aucune PR en échec dans ce premier jet.")}
      <h2>Vulnérabilités restantes</h2>
      ${asHtmlList(vulnerabilities, "Aucune vulnérabilité remontée par le placeholder.")}
      <h2>Actions manuelles recommandées</h2>
      ${asHtmlList(actions, "Aucune action manuelle supplémentaire.")}
      <h2>Journal d'exécution</h2>
      ${asHtmlList(logs, "Aucun log supplémentaire.")}
    </body>
  </html>
`;

return [
  {
    json: {
      ...data,
      emailSubject: subject,
      emailText: text,
      emailHtml: html,
      executionLog: logs.join("\n")
    }
  }
];
